"""FIPS-mode PBKDF2-HMAC password hashing and verification.

Allowed digests: "sha256", "sha512", "sha1" (legacy only).
New hashes with "sha1" raise PermissionError per org-owasp policy.
"""
import pbkdf2_hasher as _pbkdf2


def fips_password_hash(password: str, digest: str) -> str:
    """Return a PBKDF2-HMAC password hash string for the given digest.

    Allowed digests: "sha256", "sha512", "sha1".
    For "sha1", raises PermissionError as new hashes with SHA1 are disallowed.
    """
    if digest == "sha1":
        raise PermissionError("PBKDF2-HMAC-SHA1 is legacy only and disallowed for new hashes")
    if digest not in ("sha256", "sha512"):
        raise ValueError(f"Unsupported digest: {digest}")
    return _pbkdf2.hash_pbkdf2(password, digest=digest)


def fips_verify(password: str, stored: str) -> bool:
    """Verify a password against a stored PBKDF2-HMAC hash string.

    Accepts any digest and iteration count.
    """
    return _pbkdf2.verify_pbkdf2(password, stored)

